from PIL import Image, ImageDraw
im=Image.open('pantomograph.jpg').convert('RGB'); W,H=im.size; print(W,H)
def crop(name,x1,y1,x2,y2):
    c=im.crop((int(x1*W),int(y1*H),int(x2*W),int(y2*H)))
    s=1600/c.width; c=c.resize((1600,int(c.height*s)))
    d=ImageDraw.Draw(c)
    for i in range(0,101):
        f=i/100
        if x1<=f<=x2 and i%1==0:
            X=(f-x1)*W*s; d.line([(X,0),(X,c.height)],fill=(255,0,0) if i%5==0 else (255,150,150),width=2 if i%5==0 else 1); 
            if i%5==0: d.text((X+2,2),str(i),fill=(255,255,0))
        if y1<=f<=y2:
            Y=(f-y1)*H*s; d.line([(0,Y),(c.width,Y)],fill=(0,255,0) if i%5==0 else (150,255,150),width=2 if i%5==0 else 1)
            if i%5==0: d.text((2,Y+2),str(i),fill=(255,255,0))
    c.save('/tmp/c/'+name+'.png')
